import json
with open('/Users/nemesis/Projects/my-projects/catalyst/skills/handoff/evals/snapshots/1-run0.jsonl') as f:
    for line in f:
        d = json.loads(line)
        # print tool uses / results
        msg = d.get('message', {})
        content = msg.get('content')
        if isinstance(content, list):
            for c in content:
                if c.get('type') in ('tool_use',):
                    print('TOOL_USE:', c.get('name'), json.dumps(c.get('input'))[:500])
                if c.get('type') == 'tool_result':
                    txt = c.get('content')
                    if isinstance(txt, list):
                        txt = ' '.join(t.get('text','') for t in txt if isinstance(t,dict))
                    print('TOOL_RESULT:', str(txt)[:500])
                if c.get('type') == 'text':
                    print('TEXT:', c.get('text')[:500])
"

